export function getStateByName(name: string): StateInfo | undefined {
  return INDIA_STATES.find((s) => s.name === name);
}

// Demo credential-style password patterns (mirrors backend/credentials.py convention).
// These are DEFAULT/reference passwords only — the login gate lets an officer
// set their own password on first access, which then overrides the default.
export function defaultStatePlannerPassword(stateCode: string): string {
  return `SP@${stateCode}PLAN2026`;
}

export function defaultDistrictCollectorPassword(stateCode: string, district: string): string {
  const distCode = district.toUpperCase().replace(/[^A-Z]/g, "").slice(0, 6);
  return `DC@${stateCode}${distCode}2026`;
}
